import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

const Home = () => {
  const [username, setUsername] = useState('');
  const [roomCode, setRoomCode] = useState('');
  const [isCreating, setIsCreating] = useState(false);
  const [isJoining, setIsJoining] = useState(false);
  const [isDemoMode, setIsDemoMode] = useState(false);
  const navigate = useNavigate();

  const createRoom = async () => {
    if (!username.trim()) {
      alert('✨ Please enter your name to continue!');
      return;
    }

    setIsCreating(true);
    
    // Check if backend is available
    try {
      const response = await fetch('http://localhost:8080/api/rooms/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ username }),
      });

      if (response.ok) {
        const data = await response.json();
        localStorage.setItem('userId', data.userId);
        localStorage.setItem('username', username);
        localStorage.setItem('role', data.role);
        localStorage.setItem('demoMode', 'false');
        navigate(`/room/${data.roomId}`);
      } else {
        throw new Error('Backend not available');
      }
    } catch (error) {
      // If backend fails, offer demo mode
      console.log('Backend not available, switching to demo mode');
      const confirmDemo = window.confirm(
        '⚠️ Backend server not found!\n\n' +
        'Would you like to try DEMO MODE?\n\n' +
        'In Demo Mode, you can test the UI with mock data.\n' +
        '(Note: Real sync won\'t work without backend)'
      );
      
      if (confirmDemo) {
        startDemoMode();
      }
    } finally {
      setIsCreating(false);
    }
  };

  const joinRoom = async () => {
    if (!username.trim()) {
      alert('✨ Please enter your name first!');
      return;
    }
    if (!roomCode.trim()) {
      alert('🔑 Please enter a room code to join!');
      return;
    }

    setIsJoining(true);
    
    try {
      const response = await fetch('http://localhost:8080/api/rooms/join', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ roomId: roomCode, username }),
      });

      if (response.ok) {
        const data = await response.json();
        localStorage.setItem('userId', data.userId);
        localStorage.setItem('username', username);
        localStorage.setItem('role', data.role);
        localStorage.setItem('demoMode', 'false');
        navigate(`/room/${roomCode}`);
      } else {
        throw new Error('Room not found');
      }
    } catch (error) {
      // If backend fails, offer demo mode
      const confirmDemo = window.confirm(
        '⚠️ Backend server not found!\n\n' +
        'Would you like to try DEMO MODE?\n\n' +
        'In Demo Mode, you can test the UI with mock data.\n' +
        '(Note: Real sync won\'t work without backend)'
      );
      
      if (confirmDemo) {
        startDemoMode();
      }
    } finally {
      setIsJoining(false);
    }
  };

  const startDemoMode = () => {
    setIsDemoMode(true);
    // Generate demo room ID
    const demoRoomId = 'DEMO-' + Math.random().toString(36).substr(2, 6).toUpperCase();
    const demoUserId = 'demo-' + Math.random().toString(36).substr(2, 8);
    
    localStorage.setItem('userId', demoUserId);
    localStorage.setItem('username', username);
    localStorage.setItem('role', 'HOST');
    localStorage.setItem('demoMode', 'true');
    localStorage.setItem('demoRoomId', demoRoomId);
    
    alert('🎉 Demo Mode Activated!\n\n' +
          'You can now test the UI with mock data.\n' +
          'Note: Real synchronization requires backend server.\n\n' +
          `Your Demo Room ID: ${demoRoomId}`);
    
    navigate(`/room/${demoRoomId}`);
  };

  return (
    <div className="home-container">
      <div className="home-card fade-in-up">
        <h1>🎬 YouTube Watch Party</h1>
        <p>Watch YouTube videos together with friends in real-time!<br />Sync, chat, and enjoy together! 🚀</p>
        
        <div className="input-group">
          <input
            type="text"
            placeholder="✨ Enter your awesome name"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && createRoom()}
          />
        </div>

        <div className="action-buttons">
          <button 
            className="btn btn-primary"
            onClick={createRoom}
            disabled={isCreating}
          >
            {isCreating ? (
              <>
                <span className="loading"></span> Creating...
              </>
            ) : (
              '✨ Create New Party'
            )}
          </button>
          
          <div className="divider">OR</div>
          
          <div className="join-section">
            <input
              type="text"
              placeholder="🔑 Enter room code"
              value={roomCode}
              onChange={(e) => setRoomCode(e.target.value.toUpperCase())}
              onKeyPress={(e) => e.key === 'Enter' && joinRoom()}
            />
            <button 
              className="btn btn-primary"
              onClick={joinRoom}
              disabled={isJoining}
            >
              {isJoining ? (
                <>
                  <span className="loading"></span> Joining...
                </>
              ) : (
                '🚪 Join Party'
              )}
            </button>
          </div>
        </div>

        <div className="features">
          <div className="feature-badge">Real-time Sync</div>
          <div className="feature-badge">Role-based Access</div>
          <div className="feature-badge">Live Chat</div>
          <div className="feature-badge">YouTube Integration</div>
        </div>

        {!isCreating && !isJoining && (
          <div style={{ marginTop: '20px', fontSize: '12px', color: '#999' }}>
            💡 Tip: If backend is not running, you'll be prompted to use Demo Mode
          </div>
        )}
      </div>
    </div>
  );
};

export default Home;
